    const w = {start: '03:00', end: '05:00', tz: 'local' as const};
    expect(inWindow(localFour, w)).toBe(true);
    const localSix = new Date(2026, 4, 15, 6, 0, 0);
    expect(inWindow(localSix, w)).toBe(false);
  });
});

